PR · Kirish tayyor.kod:
var inp = $("PR · QOIDALAR").first().json;
var sj = $("PR · s_jadval").all().map(function(i){return i.json;});
var ps = $("PR · pasport").all().map(function(i){return i.json;});
var mh = $("PR · manba_havolalari").all().map(function(i){return i.json;});
var mavzu = String(inp.mavzu_kod||"");
var faktlar = sj.filter(function(r){ return String(r.mavzu_kodlar||"").split(",").map(function(s){return s.trim();}).indexOf(mavzu)>=0; })
  .map(function(r){ var h = mh.filter(function(x){return x.s_id===r.s_id;})[0]||{}; return { s_id:r.s_id, ekran:r.matn_tr, manba:r.manba, manba_toliq:r.manba_toliq, rang:r.rang, meta_tiktok:r.meta_tiktok, daraja:r.daraja, havola:h.havola||"", skrinshot_ruxsat:h.skrinshot_ruxsat||"" }; });
var pas = ps.filter(function(r){return r.mahsulot_kod===inp.mahsulot_kod;})[0]||{};
var xato=[]; if(!faktlar.length) xato.push("fakt yoq"); if(!pas.mahsulot_kod) xato.push("pasport yoq"); if(!inp.tts_matn) xato.push("tts_matn yoq");
return [{ json: Object.assign({}, inp, { faktlar:faktlar, pasport:pas, platforma_qoida:(inp.qoidalar.platforma||{})[inp.mahsulot_kod]||{}, kirish_xato:xato }) }];

